 cards.append(f'''<article class="module" id="{m['id']}" data-stage="{m['stage']}">
 <div class="module-heading"><span class="number">{i:02}</span><div><div class="meta">{m['weeks']} · {m['stage']} · {m['level']}</div><h3>{m['title']}</h3><p class="subtitle">{m['subtitle']}</p></div><label class="done"><input type="checkbox" data-complete="{m['id']}" aria-label="標記 {m['title']} 已完成"><span>已完成</span></label></div>
 <p>{m['intro']}</p><p class="prereq"><strong>先備知識</strong>　{m['prereq']}</p>
 <h4>從原始資料開始</h4><ul class="sources">{sources}</ul>
 <details class="lesson"><summary>展開導讀與實作 <span aria-hidden="true">＋</span></summary><div class="lesson-body"><h4>三個核心觀念</h4><ol>{concepts}</ol><div class="formula">{e(m['formula'])}</div><h4>閱讀路徑</h4><p>{m['reading']}</p><h4>動手實作 <span class="tag">課程設計</span></h4><p>{m['lab']}</p><div class="output"><strong>交付成果</strong><p>{m['deliverable']}</p></div><h4>讀完，試著回答</h4>{questions}<p class="pitfall"><strong>辨析</strong>　{m['pitfall']}</p></div></details></article>''')
